const ids=['1:24','1:27','6:32','6:20','6:37','6:23'];
const out={};
for(const id of ids){
  const n=await figma.getNodeByIdAsync(id);
  if(!n){out[id]=null;continue;}
  const dump=(n,d)=>{
    const o={type:n.type,name:n.name,w:Math.round(n.width),h:Math.round(n.height)};
    if('layoutMode' in n)o.layoutMode=n.layoutMode;
    if('cornerRadius' in n)o.radius=n.cornerRadius;
    if(n.fills&&Array.isArray(n.fills))o.fills=n.fills.map(f=>f.type==='SOLID'?('SOLID '+JSON.stringify(f.color)):f.type);
    if(n.strokes&&n.strokes.length)o.strokes=n.strokes.map(f=>f.type==='SOLID'?JSON.stringify(f.color):f.type);
    if(n.type==='TEXT'){o.font=n.fontName;o.size=n.fontSize;o.chars=n.characters;o.align=n.textAlignHorizontal;}
    if(d>0&&n.children)o.children=n.children.map(c=>dump(c,d-1));
    return o;
  };
  out[n.name]=dump(n,3);
}
return JSON.stringify(out,null,1);

