function T(p,chars,fam,style,size,color){const t=figma.createText();t.fontName={family:fam,style};t.fontSize=size;t.characters=chars;t.fills=[sol(color)];p.appendChild(t);return t}
function Fr(p,w,h,fill){const f=figma.createFrame();f.resize(w,h);f.fills=fill?[sol(fill)]:[];if(p)p.appendChild(f);return f}
function AL(f,dir,gap,pl,pt,pr,pb){f.layoutMode=dir;f.itemSpacing=gap;f.paddingLeft=pl;f.paddingTop=pt;f.paddingRight=pr;f.paddingBottom=pb;return f}
